import { bigint, index, integer, pgTable, text, timestamp } from "drizzle-orm/pg-core";

import { user } from "./schema";

// Tables ErgStats owns. schema.ts is generated by Better Auth (`pnpm auth:schema`)
// and would lose anything added to it by hand.

/**
 * Reports agents send with the send_feedback MCP tool: something the user asked
 * that the tools couldn't answer, or a tool that failed or misled. Deleted with
 * the account.
 */
export const agentFeedback = pgTable(
  "agent_feedback",
  {
    id: text("id")
      .primaryKey()
      .$defaultFn(() => crypto.randomUUID()),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    /** missing_capability, issue or other. */
    type: text("type").notNull(),
    summary: text("summary").notNull(),
    /** The tool the report is about, as the agent named it. */
    tool: text("tool"),
    /** Which app sent it: the OAuth client's host, "registered" for dynamically registered clients, or "api_key". */
    client: text("client"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (table) => [index("agent_feedback_userId_createdAt_idx").on(table.userId, table.createdAt)],
);

/**
 * The request budget of a user calling /mcp with an OAuth token: how many
 * requests they have made in the current window and when it started. API
 * keys carry their own budget in Better Auth's apikey table. One row per
 * user, deleted with the account.
 */
export const mcpRequestQuota = pgTable("mcp_request_quota", {
  userId: text("user_id")
    .primaryKey()
    .references(() => user.id, { onDelete: "cascade" }),
  /** Start of the current window, in milliseconds since the epoch. */
  windowStart: bigint("window_start", { mode: "number" }).notNull(),
  /** Requests made in the window, counting the ones that were refused. */
  count: integer("count").notNull(),
});
